def shortest_path(edges, start, end):
    # Check for negative weights
    for u, v, w in edges:
        if w < 0:
            raise ValueError("Negative edge weight detected")

    # If start and end are the same node
    if start == end:
        return (0, [start])

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    all_nodes = set()
    for u, v, w in edges:
        graph[u].append((v, w))
        all_nodes.add(u)
        all_nodes.add(v)

    # Dijkstra's algorithm
    import heapq
    dist = {node: float('inf') for node in all_nodes}
    dist[start] = 0
    prev = {}
    visited = set()

    heap = [(0, start)]

    while heap:
        d, node = heapq.heappop(heap)
        if node in visited:
            continue
        visited.add(node)

        if node == end:
            break

        for neighbor, weight in graph[node]:
            if neighbor in visited:
                continue
            new_dist = dist[node] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                prev[neighbor] = node
                heapq.heappush(heap, (new_dist, neighbor))

    # Check if we reached the end
    if dist[end] == float('inf'):
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current != start:
        path.append(current)
        current = prev[current]
    path.append(start)
    path.reverse()

    return (dist[end], path)
